const s=input.state,e=input.event;
const fmt=n=>{const r=Math.round(n*100)/100;return String(r);};
const recalc=()=>{
 const f=s.originalServings>0?s.targetServings/s.originalServings:1;
 s.factorText='×'+fmt(f);
 for(const it of s.ingredients){it.amountText=fmt(it.amount)+' '+it.unit+' → '+fmt(it.amount*f)+' '+it.unit;}
 s.itemCount=s.ingredients.length;s.hasItems=s.itemCount>0;s.empty=!s.hasItems;
 s.isEditing=!!s.editingId;s.adding=!s.isEditing;
};
if(e.type==='action'||e.type==='liveInput'){
 const a=e.actionId,v=e.value;
 if(a==='originalServings'||a==='targetServings'){s[a]=Math.max(1,Number(v)||1);recalc();}
 else if(a==='draftName'){s.draftName=String(v||'');}
 else if(a==='draftAmount'){const n=Number(v);if(isFinite(n))s.draftAmount=n;}
 else if(a==='draftUnit'){s.draftUnit=String(v||'g');}
 else if(a==='add'||a==='save'){
  const name=(s.draftName||'').trim();
  if(name&&s.draftAmount>0){
   if(a==='save'){const it=s.ingredients.find(x=>x.id===s.editingId);if(it){it.name=name;it.amount=s.draftAmount;it.unit=s.draftUnit;}}
   else if(s.ingredients.length<50){s.ingredients.push({id:'i'+s.nextId,name:name,amount:s.draftAmount,unit:s.draftUnit,amountText:''});s.nextId++;}
   s.draftName='';s.draftAmount=100;s.draftUnit='g';s.editingId='';recalc();
  }
 }
 else if(a==='edit'){const it=s.ingredients.find(x=>x.id===v.key);if(it){s.editingId=it.id;s.draftName=it.name;s.draftAmount=it.amount;s.draftUnit=it.unit;recalc();}}
 else if(a==='cancelEdit'){s.editingId='';s.draftName='';s.draftAmount=100;s.draftUnit='g';recalc();}
 else if(a==='remove'){s.ingredients=s.ingredients.filter(x=>x.id!==v.key);if(s.editingId===v.key)s.editingId='';recalc();}
 else if(a==='reset'){
  s.originalServings=4;s.targetServings=6;s.nextId=2;
  s.ingredients=[{id:'i1',name:'Flour',amount:300,unit:'g',amountText:'300 g → 450 g'}];
  s.draftName='';s.draftAmount=100;s.draftUnit='g';s.editingId='';recalc();
 }
}
return {state:s};
